// Bundles src/cli.ts into one readable (not minified) file with no runtime dependencies.
import { build } from 'esbuild';

await build({
  entryPoints: ['src/cli.ts'],
  outfile: process.env.PROMPTLANX_OUTFILE ?? 'plugins/promptlanx/dist/promptlanx-hook.js',
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node18',
  minify: false,
  legalComments: 'inline',
  charset: 'utf8',
  banner: {
    js: [
      '// PromptLanx for Claude Code: UserPromptSubmit hook.',
      '// SPDX-License-Identifier: Apache-2.0',
      '// GENERATED by scripts/build.mjs from src/. Do not edit; edit src/ and run `npm run build`.',
      '// Runs locally with plain `node`. No dependencies, no network, no file writes.',
    ].join('\n'),
  },
  logLevel: process.env.PROMPTLANX_OUTFILE ? 'warning' : 'info',
});
